# ==========================================
# JOGADOR (HERÓI)
# ==========================================
ENTITY player
TRANSFORM 0.0 0.0 0.0
PHYSICS 0.0 0.0 0.0 0.90
COLLISION -1.0 -1.0 -1.0 1.0 2.0 1.0 0 0
PLAYER_CONTROL
HUD 100.0 2.0 10.0
HEALTH 100.0
# WeaponControl: AimMode (1=Camera)
WEAPON_CONTROL 1

# --- ARMAS DO JOGADOR ---

# Laser Esquerdo (Braço)
ENTITY p_laser_L
TRANSFORM 0 0 0
WEAPON WEAPON_PULSE_LASER 0.5 150.0 5.0 500.0 2.0 2 0.1
ATTACHMENT player -1.70 5.50 1.50

# Laser Direito (Braço)
ENTITY p_laser_R
TRANSFORM 0 0 0
WEAPON WEAPON_PULSE_LASER 0.5 150.0 5.0 500.0 2.0 2 0.1
ATTACHMENT player 1.70 5.50 1.50

# Missil Esquerdo (Ombro)
ENTITY p_missile_L
TRANSFORM 0 0 0
WEAPON WEAPON_MISSILE_LAUNCHER 5.0 60.0 25.0 1000.0 5.0 20 0.115
ATTACHMENT player -1.70 7.00 1.50

# Missil Direito (Ombro)
ENTITY p_missile_R
TRANSFORM 0 0 0
WEAPON WEAPON_MISSILE_LAUNCHER 5.0 60.0 25.0 1000.0 5.0 20 0.115
ATTACHMENT player 1.70 7.00 1.50

# Vínculos (Loadout) - Isso ativa os grupos automaticamente
LINK_WEAPON player 0 p_laser_L 0 1
LINK_WEAPON player 1 p_laser_R 0 1
LINK_WEAPON player 2 p_missile_L 1 0
LINK_WEAPON player 3 p_missile_R 1 0


# ==========================================
# ESTRUTURA: TORRE GIGANTE (OBJETIVO)
# ==========================================
ENTITY turret_struct
TRANSFORM 0.0 -15.0 -650.0
# Render ID 4 (Torre)
RENDER 4 255 255 255 255
# Colisão Grande (50m x 100m x 50m)
COLLISION -25.0 0.0 -25.0 25.0 100.0 25.0 1 0
# OBJECTIVE 0 1 1 (Tipo 0, Primario, Ativo) - Se tiver o componente

